// 取得前面三個 Postgres 節點的結果
const cfg   = $('設定').first().json;
const s     = $('營收總覽').first().json;
const top   = $('熱銷前五名').all().map(i => i.json);
const hours = $('各時段營收').all().map(i => i.json).filter(h => h.時段 !== undefined);

const n   = v => Number(v || 0);
const fmt = v => n(v).toLocaleString('zh-TW');

// 和上週同一天比較
let compare = '上週同日無資料';
if (n(s.上週同日營收) > 0) {
  const pct = ((n(s.營收) - n(s.上週同日營收)) / n(s.上週同日營收) * 100).toFixed(1);
  compare = pct >= 0
    ? `<span style="color:#16a34a">▲ ${pct}%</span> 比上週同日`
    : `<span style="color:#dc2626">▼ ${Math.abs(pct).toFixed(1)}%</span> 比上週同日`;
}

const card = (label, value) => `
  <td style="padding:12px;background:#fff7ed;border-radius:10px;text-align:center">
    <div style="font-size:13px;color:#9a3412">${label}</div>
    <div style="font-size:22px;font-weight:bold;color:#7c2d12">${value}</div>
  </td>`;

const medal = ['🥇', '🥈', '🥉', '4.', '5.'];
const topRows = top.map((t, i) => `
  <tr>
    <td style="padding:6px 8px">${medal[i]}</td>
    <td style="padding:6px 8px">${t.品名}</td>
    <td style="padding:6px 8px;color:#6b7280">${t.類別}</td>
    <td style="padding:6px 8px;text-align:right">${fmt(t.份數)} 份</td>
    <td style="padding:6px 8px;text-align:right">$${fmt(t.銷售額)}</td>
  </tr>`).join('');

// 用 div 寬度畫簡單的長條圖（Email 不支援 JavaScript 圖表）
const maxRev = Math.max(1, ...hours.map(h => n(h.營收)));
const hourRows = hours.map(h => `
  <tr>
    <td style="padding:4px 8px;white-space:nowrap">${String(h.時段).padStart(2, '0')}:00</td>
    <td style="padding:4px 8px;width:100%">
      <div style="background:#fb923c;height:16px;border-radius:4px;width:${Math.round(n(h.營收) / maxRev * 100)}%"></div>
    </td>
    <td style="padding:4px 8px;text-align:right;white-space:nowrap">$${fmt(h.營收)}（${h.訂單數} 單）</td>
  </tr>`).join('');

const html = n(s.訂單數) === 0
  ? `<p>${cfg.報表日期} 沒有任何訂單（公休日？），請確認資料是否正確。</p>`
  : `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto">
  <h2 style="color:#7c2d12">🍳 ${cfg.店名}｜${cfg.報表日期} 營收日報</h2>
  <table style="width:100%;border-spacing:8px"><tr>
    ${card('營收', '$' + fmt(s.營收))}
    ${card('訂單數', fmt(s.訂單數) + ' 單')}
    ${card('客單價', '$' + fmt(s.客單價))}
  </tr></table>
  <p style="margin:4px 8px">${compare}（上週同日 $${fmt(s.上週同日營收)}）・外送平台 ${fmt(s.外送單數)} 單</p>

  <h3 style="color:#7c2d12;margin-top:24px">🔥 熱銷前五名</h3>
  <table style="width:100%;border-collapse:collapse;font-size:14px">${topRows}</table>

  <h3 style="color:#7c2d12;margin-top:24px">⏰ 各時段營收</h3>
  <table style="width:100%;border-collapse:collapse;font-size:14px">${hourRows}</table>

  <p style="color:#9ca3af;font-size:12px;margin-top:24px">此信由 n8n 自動產生</p>
</div>`;

return [{
  json: {
    to: cfg.老闆信箱,
    subject: `🍳 ${cfg.報表日期} 營收日報：$${fmt(s.營收)}（${fmt(s.訂單數)} 單）`,
    html,
  },
}];
